begin;
alter table public.nexus_cities add constraint nexus_cities_city_id_key unique(city_id);
alter table public.nexus_cities add column if not exists name text not null default 'Ma ville 3B';
alter table public.nexus_cities add column if not exists origin_country text not null default 'France';
alter table public.nexus_cities add column if not exists visibility text not null default 'private';
alter table public.nexus_cities add column if not exists visitors bigint not null default 0;
alter table public.nexus_cities add column if not exists created_at timestamptz not null default now();
alter table public.nexus_cities add constraint nexus_cities_origin_country_check check(origin_country in ('France','Italie','Estonie','Turquie','Algérie','Tunisie','Maroc','Espagne'));
alter table public.nexus_cities add constraint nexus_cities_visibility_check check(visibility in ('private','friends','public'));
alter table public.nexus_cities add constraint nexus_cities_name_check check(length(name) between 2 and 40);
alter table public.nexus_cities add constraint nexus_cities_visitors_check check(visitors>=0);
create table public.nexus_city_buildings(code text primary key,name text not null,category text not null check(category in ('home','shop','culture','sport','nature','monument','community','road','decoration')),country text check(country is null or country in ('France','Italie','Estonie','Turquie','Algérie','Tunisie','Maroc','Espagne')),unlock_level integer not null default 1 check(unlock_level between 1 and 100),cost_coins bigint not null default 0 check(cost_coins>=0),footprint jsonb not null default '{"w":1,"h":1}'::jsonb check(jsonb_typeof(footprint)='object'),permanent boolean not null default true,active boolean not null default true,metadata jsonb not null default '{}'::jsonb check(jsonb_typeof(metadata)='object'));
create table public.nexus_city_placements(id uuid primary key default gen_random_uuid(),city_id uuid not null references public.nexus_cities(city_id) on delete cascade,building_code text not null references public.nexus_city_buildings(code),x integer not null check(x between -500 and 500),z integer not null check(z between -500 and 500),rotation smallint not null default 0 check(rotation in (0,90,180,270)),variant text,placed_at timestamptz not null default now(),unique(city_id,x,z));
create table public.nexus_city_unlocks(city_id uuid not null references public.nexus_cities(city_id) on delete cascade,building_code text not null references public.nexus_city_buildings(code),unlocked_at timestamptz not null default now(),source text not null default 'level' check(source in ('starter','level','achievement','world','event','collection')),primary key(city_id,building_code));
create table public.nexus_city_visits(city_id uuid not null references public.nexus_cities(city_id) on delete cascade,visitor_id uuid not null references auth.users(id) on delete cascade,last_visit timestamptz not null default now(),visits integer not null default 1 check(visits>0),primary key(city_id,visitor_id));
insert into public.nexus_city_buildings(code,name,category,unlock_level,cost_coins,metadata) values ('CITY_HALL_3B','Hôtel de Ville 3B','community',1,0,'{"starter":true,"style":"black-gold-matrix"}'),('HOME_ORIGIN','Maison Origine','home',1,0,'{"starter":true}'),('ROAD_MATRIX','Route Matrix','road',1,0,'{"starter":true}'),('PARK_UNITY','Parc de l’Unité','nature',2,150,'{}'),('SHOP_3B','Boutique 3B','shop',3,300,'{}'),('ARENA_1618','Arène 16-18','sport',5,750,'{}'),('MANGA_HALL','Maison 3B ORIGINS','culture',6,900,'{}'),('MONUMENT_EIGHT_DOORS','Monument des Huit Portes','monument',8,1600,'{}');
alter table public.nexus_cities enable row level security;alter table public.nexus_city_buildings enable row level security;alter table public.nexus_city_placements enable row level security;alter table public.nexus_city_unlocks enable row level security;alter table public.nexus_city_visits enable row level security;
revoke all on public.nexus_city_buildings,public.nexus_city_placements,public.nexus_city_unlocks,public.nexus_city_visits from public,anon,authenticated;grant select on public.nexus_city_buildings,public.nexus_city_placements,public.nexus_city_unlocks to authenticated;grant all on public.nexus_city_buildings,public.nexus_city_placements,public.nexus_city_unlocks,public.nexus_city_visits to service_role;
drop policy if exists nexus_city_read_own_or_public on public.nexus_cities;create policy nexus_city_read_own_or_public on public.nexus_cities for select to authenticated using(user_id=(select auth.uid()) or visibility='public');
create policy nexus_city_buildings_read on public.nexus_city_buildings for select to authenticated using(active=true);
create policy nexus_city_placements_read on public.nexus_city_placements for select to authenticated using(exists(select 1 from public.nexus_cities c where c.city_id=nexus_city_placements.city_id and (c.user_id=(select auth.uid()) or c.visibility='public')));
create policy nexus_city_unlocks_read_own on public.nexus_city_unlocks for select to authenticated using(exists(select 1 from public.nexus_cities c where c.city_id=nexus_city_unlocks.city_id and c.user_id=(select auth.uid())));
create index nexus_city_public_updated_idx on public.nexus_cities(visibility,updated_at desc);create index nexus_city_placements_city_idx on public.nexus_city_placements(city_id,placed_at);create index nexus_city_unlocks_city_idx on public.nexus_city_unlocks(city_id,unlocked_at);
commit;
